                <div className="flex flex-col">
                  {recentFailures.slice(0, 5).map((failure) => (
                    <div key={failure.id} className="flex flex-col space-y-2 border-b border-red-500/10 p-6 last:border-0 hover:bg-red-500/5 transition-colors">
