vi.setConfig({ hookTimeout: 30000, testTimeout: 30000 });

let testUser: User;
let upProject: Project;
let downProject: Project;
let inactiveProject: Project;

describe("User Dashboard Service", () => {
    beforeAll(async () => {
        testUser = await prisma.user.create({
